local function IsRaidIconID(value)
    return type(value) == "number" and value > 0 and value < math.huge and value % 1 == 0
end--[[APR_DIAG]]
IsRaidIconID = APRTrace("APR-Core/utils/TargetUtils.lua:285:IsRaidIconID#1018", IsRaidIconID)--[[/APR_DIAG]]

-- Parse once at the route/UI boundary; never mutate the authored list.
function APR:NormalizeRaidIconTargets(value)
    if IsRaidIconID(value) then return { value } end
    if type(value) ~= "table" then return {} end
    if value.npcID then value = { value } end
    local result, seen, count = {}, {}, 0
    for key, id in pairs(value) do
        if not IsRaidIconID(key) or key > #value or not IsRaidIconID(type(id) == "table" and id.npcID or id) then return {} end
        count = count + 1
    end
    if count ~= #value then return {} end
    for _, entry in ipairs(value) do
        local id = type(entry) == "table" and entry.npcID or entry
        if not seen[id] then
            result[#result + 1], seen[id] = id, true
        end
    end
    return result
end--[[APR_DIAG]]
APR.NormalizeRaidIconTargets =
    APRTrace("APR-Core/utils/TargetUtils.lua:290:APR:NormalizeRaidIconTargets#1019", APR.NormalizeRaidIconTargets)--[[/APR_DIAG]]

-- An explicit list owns targeting; action-derived targets remain legacy fallbacks.
function APR:GetStepRaidIconTargets(step)
    return step
        and (
            step.RaidIcon
            or (step.KillNPC and step.KillNPC.npcID)
            or (step.DroppableQuest and step.DroppableQuest.MobId)
        )
end--[[APR_DIAG]]
APR.GetStepRaidIconTargets =
    APRTrace("APR-Core/utils/TargetUtils.lua:306:APR:GetStepRaidIconTargets#1020", APR.GetStepRaidIconTargets)--[[/APR_DIAG]]

--- Gets the raid icon NPC name for a given NPC ID.
--- @param npcID number The NPC ID to look up
--- @return string|nil The raid icon NPC name, or nil if not found
function APR:GetRaidIconNpcName(npcID)
    if not APRSecret:CanAccessValue(npcID) or type(npcID) ~= "number" then
        return nil
    end
    self:PrepareNPCNameLocale()
    local name = APRData and APRData.NPCList and APRData.NPCList[npcID]
    if not APRSecret:CanAccessValue(name) then name = nil end
    local version = self.GetGameVersion and self:GetGameVersion() or "forever"
    local journal = self.DungeonNPCJournal and self.DungeonNPCJournal[version]
    local entry = journal and journal[npcID]
    if not name and entry and EJ_GetCreatureInfo then
        local _, localized = EJ_GetCreatureInfo(entry[2], entry[1])
        if
            APRSecret:CanAccessValue(localized)
            and type(localized) == "string"
            and localized ~= ""
            and localized ~= UNKNOWN
        then
            name = localized
            self:RememberNPCName(npcID, name)
        end
    end
    if not name and C_TooltipInfo and C_TooltipInfo.GetHyperlink then
        local tooltip = C_TooltipInfo.GetHyperlink("unit:Creature-0-0-0-0-" .. npcID .. "-0")
        local lines = APRSecret:CanAccessTable(tooltip) and tooltip.lines
        local first = APRSecret:CanAccessTable(lines) and lines[1]
        local localized = APRSecret:CanAccessTable(first) and first.leftText
        if
            APRSecret:CanAccessValue(localized)
            and type(localized) == "string"
            and localized ~= ""
            and localized ~= UNKNOWN
        then
            name = localized
            self:RememberNPCName(npcID, name)
        end
    end
    local localized = name ~= nil
    if not name and self.GetCurrentStep then
        local step = self:GetCurrentStep()
        if step and step.KillNPC and step.KillNPC.npcID == npcID then name = step.KillNPC.name end
    end
    if not APRSecret:CanAccessValue(name) or type(name) ~= "string" or name == "" or name:find("[\r\n|%[%];]") then
        return nil
    end
    return name, localized
end--[[APR_DIAG]]
APR.GetRaidIconNpcName =
    APRTrace("APR-Core/utils/TargetUtils.lua:214:APR:GetRaidIconNpcName#16", APR.GetRaidIconNpcName)--[[/APR_DIAG]]

--- Finds the unit token for a raid target with the specified NPC ID.
---
--- @param npcID number The NPC ID to search for among raid targets.
--- @return string|nil unitToken The unit token (e.g., "raid1", "raid2") if found, nil otherwise.
---
--- @usage
--- local token = APR:FindRaidIconUnitToken(12345)
--- if token then
---     print("Found unit: " .. token)
--- end
local function PublicUnitFlag(api, unit, expected)
    if not api then return false end
    local value = api(unit)
    return APRSecret:CanAccessValue(value) and value == expected
end--[[APR_DIAG]]
