local function IsLiveRaidIconUnit(unit)
    return PublicUnitFlag(UnitExists, unit, true)
        and PublicUnitFlag(UnitIsDeadOrGhost, unit, false)
        and PublicUnitFlag(UnitIsPlayer, unit, false)
end--[[APR_DIAG]]
